local IncenseMolderMaker = {}
local PRODUCTS = {
    iron_incensemolder = { name = "Železni oblikovalec kadila", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni oblikovalec kadila za glasbila." },
    bronze_incensemolder = { name = "Bronast oblikovalec kadila", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast oblikovalec kadila za fino glasbo." },
    silver_incensemolder = { name = "Srebrn oblikovalec kadila", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn oblikovalec kadila za plemiške glasbenike." },
    gilded_incensemolder = { name = "Pozlačen oblikovalec kadila", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen oblikovalec kadila za dvorne glasbenike." },
    jewel_set_incensemolder = { name = "Draguljast oblikovalec kadila", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast oblikovalec kadila za kraljevske glasbenike." },
    royal_sovereign_incensemolder = { name = "Kraljevski suveren oblikovalec kadila", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren oblikovalec kadila z biseri za krono." },
}
local BUILDINGS = {
    incensemolder_workshop = { name = "Incensemolder delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    incensemolder_house = { name = "Incensemolder hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_incensemolder_atelier = { name = "Mojstrski incensemolder atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_incensemolder_palace = { name = "Suverena incensemolder palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
IncenseMolderMaker.ironStock = 12; IncenseMolderMaker.bronzeStock = 10; IncenseMolderMaker.woodStock = 16; IncenseMolderMaker.leatherStock = 12; IncenseMolderMaker.silverStock = 8; IncenseMolderMaker.goldStock = 6; IncenseMolderMaker.jewelStock = 4; IncenseMolderMaker.pearlStock = 4
IncenseMolderMaker.productStock = {}; IncenseMolderMaker.buildings = {}; IncenseMolderMaker.maker = nil; IncenseMolderMaker.activeMaking = {}; IncenseMolderMaker.totalProducts = 0; IncenseMolderMaker.dayTimer = 0
function IncenseMolderMaker.init() IncenseMolderMaker.ironStock=12; IncenseMolderMaker.bronzeStock=10; IncenseMolderMaker.woodStock=16; IncenseMolderMaker.leatherStock=12; IncenseMolderMaker.silverStock=8; IncenseMolderMaker.goldStock=6; IncenseMolderMaker.jewelStock=4; IncenseMolderMaker.pearlStock=4; IncenseMolderMaker.productStock={}; IncenseMolderMaker.buildings={}; IncenseMolderMaker.maker=nil; IncenseMolderMaker.activeMaking={}; IncenseMolderMaker.totalProducts=0; IncenseMolderMaker.dayTimer=0; print("[IncenseMolderMaker] Royal Incense Molder Maker System initialized (6 products, 4 buildings)") end
function IncenseMolderMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; IncenseMolderMaker.maker={name=n or ("Kadilar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kadilar najet: %s (spretnost: %d)",IncenseMolderMaker.maker.name,s),"success") end; return true end
function IncenseMolderMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function IncenseMolderMaker.build(id) local ok,e=IncenseMolderMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(IncenseMolderMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function IncenseMolderMaker.getQualityBonus() local b=0; for _,bd in ipairs(IncenseMolderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function IncenseMolderMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and IncenseMolderMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and IncenseMolderMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and IncenseMolderMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and IncenseMolderMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and IncenseMolderMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and IncenseMolderMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and IncenseMolderMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and IncenseMolderMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #IncenseMolderMaker.buildings==0 then return false,"Potrebna kadilna delavnica" end; if not IncenseMolderMaker.maker then return false,"Potreben kadilar" end; return true end
function IncenseMolderMaker.make(pt,qty) qty=qty or 1; local ok,e=IncenseMolderMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then IncenseMolderMaker.ironStock=IncenseMolderMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then IncenseMolderMaker.bronzeStock=IncenseMolderMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then IncenseMolderMaker.woodStock=IncenseMolderMaker.woodStock-d.woodCost*qty end; if d.leatherCost then IncenseMolderMaker.leatherStock=IncenseMolderMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then IncenseMolderMaker.silverStock=IncenseMolderMaker.silverStock-d.silverCost*qty end; if d.goldCost then IncenseMolderMaker.goldStock=IncenseMolderMaker.goldStock-d.goldCost*qty end; if d.jewelCost then IncenseMolderMaker.jewelStock=IncenseMolderMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then IncenseMolderMaker.pearlStock=IncenseMolderMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if IncenseMolderMaker.maker then t=math.max(1,t-math.floor(IncenseMolderMaker.maker.skill/13)) end; table.insert(IncenseMolderMaker.activeMaking,{id="incensemolder_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function IncenseMolderMaker.completeMaking(m) local q=1.0+(IncenseMolderMaker.getQualityBonus()/100); if IncenseMolderMaker.maker then q=q+(IncenseMolderMaker.maker.skill/140) end; q=math.min(2.5,q); IncenseMolderMaker.productStock[m.productType]=(IncenseMolderMaker.productStock[m.productType] or 0)+m.quantity; IncenseMolderMaker.totalProducts=IncenseMolderMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if IncenseMolderMaker.maker then IncenseMolderMaker.maker.itemsMade=IncenseMolderMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then IncenseMolderMaker.maker.skill=math.min(100,IncenseMolderMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Oblikovalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"incensemolder.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function IncenseMolderMaker.update(dt) if not _G.state then return end; IncenseMolderMaker.dayTimer=IncenseMolderMaker.dayTimer+dt; if IncenseMolderMaker.dayTimer>=30 then IncenseMolderMaker.dayTimer=0; for i=#IncenseMolderMaker.activeMaking,1,-1 do local m=IncenseMolderMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then IncenseMolderMaker.completeMaking(m); table.remove(IncenseMolderMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(IncenseMolderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if IncenseMolderMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function IncenseMolderMaker.getStats() return {ironStock=IncenseMolderMaker.ironStock,bronzeStock=IncenseMolderMaker.bronzeStock,woodStock=IncenseMolderMaker.woodStock,leatherStock=IncenseMolderMaker.leatherStock,silverStock=IncenseMolderMaker.silverStock,goldStock=IncenseMolderMaker.goldStock,jewelStock=IncenseMolderMaker.jewelStock,pearlStock=IncenseMolderMaker.pearlStock,productStock=IncenseMolderMaker.productStock,numBuildings=#IncenseMolderMaker.buildings,hasMaker=IncenseMolderMaker.maker~=nil,makerName=IncenseMolderMaker.maker and IncenseMolderMaker.maker.name or "—",makerSkill=IncenseMolderMaker.maker and IncenseMolderMaker.maker.skill or 0,activeMaking=#IncenseMolderMaker.activeMaking,totalProducts=IncenseMolderMaker.totalProducts} end
return IncenseMolderMaker
